int vc4_get_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    u32 binning_cmdlist_size = exec->cmdlist_args.binning_cmdlist_size;
    u32 shader_records_size = exec->cmdlist_args.shader_records_size;
    u32 uniforms_size = exec->cmdlist_args.uniforms_size;
    void *binning_cmdlist, *shader_records, *uniforms;
    int ret;

    if (binning_cmdlist_size > VC4_BINNING_CMDLIST_MAX ||
        shader_records_size > VC4_SHADER_RECORDS_MAX ||
        uniforms_size > VC4_UNIFORMS_MAX) {
        return -EINVAL;
    }

    binning_cmdlist = kzalloc(binning_cmdlist_size, GFP_KERNEL);
    if (!binning_cmdlist)
        return -ENOMEM;

    shader_records = kzalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto out_free_binning;
    }

    uniforms = kzalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms) {
        ret = -ENOMEM;
        goto out_free_shader;
    }

    if (copy_from_user(binning_cmdlist, u64_to_user_ptr(exec->cmdlist_args.binning_cmdlist), binning_cmdlist_size)) {
        ret = -EFAULT;
        goto out_free_uniforms;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->cmdlist_args.shader_records), shader_records_size)) {
        ret = -EFAULT;
        goto out_free_uniforms;
    }

    if (copy_from_user(uniforms, u64_to_user_ptr(exec->cmdlist_args.uniforms), uniforms_size)) {
        ret = -EFAULT;
        goto out_free_uniforms;
    }

    ret = vc4_validate_cmdlist(dev, binning_cmdlist, binning_cmdlist_size,
                                shader_records, shader_records_size);
    if (ret)
        goto out_free_uniforms;

    exec->bo = vc4_bo_create(dev, binning_cmdlist_size + shader_records_size + uniforms_size);
    if (IS_ERR(exec->bo)) {
        ret = PTR_ERR(exec->bo);
        goto out_free_uniforms;
    }

    ret = vc4_bo_map(exec->bo);
    if (ret)
        goto out_free_bo;

    memcpy(exec->bo->vaddr, binning_cmdlist, binning_cmdlist_size);
    memcpy(exec->bo->vaddr + binning_cmdlist_size, shader_records, shader_records_size);
    memcpy(exec->bo->vaddr + binning_cmdlist_size + shader_records_size, uniforms, uniforms_size);

    ret = vc4_wait_for_render_completion(dev);
    if (ret)
        goto out_unmap_bo;

    kfree(binning_cmdlist);
    kfree(shader_records);
    kfree(uniforms);

    return 0;

out_unmap_bo:
    vc4_bo_unmap(exec->bo);
out_free_bo:
    vc4_bo_unref(exec->bo);
out_free_uniforms:
    kfree(uniforms);
out_free_shader:
    kfree(shader_records);
out_free_binning:
    kfree(binning_cmdlist);
    return ret;
}

int vc4_prepare_binning(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    size_t binning_size, shader_records_size, uniforms_size;
    void *binning_cmd_list, *shader_records, *uniforms;

    binning_size = exec->binning_cmd_list_args.size;
    shader_records_size = exec->shader_records_args.size;
    uniforms_size = exec->uniforms_args.size;

    if (binning_size + shader_records_size + uniforms_size > VC4_MAX_BINNING_SIZE)
        return -EINVAL;

    binning_cmd_list = kmalloc(binning_size, GFP_KERNEL);
    if (!binning_cmd_list)
        return -ENOMEM;

    shader_records = kmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        kfree(binning_cmd_list);
        return -ENOMEM;
    }

    uniforms = kmalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms) {
        kfree(binning_cmd_list);
        kfree(shader_records);
        return -ENOMEM;
    }

    ret = copy_from_user(binning_cmd_list, exec->binning_cmd_list_args.user_ptr, binning_size);
    if (ret) {
        ret = -EFAULT;
        goto err_free;
    }

    ret = copy_from_user(shader_records, exec->shader_records_args.user_ptr, shader_records_size);
    if (ret) {
        ret = -EFAULT;
        goto err_free;
    }

    ret = copy_from_user(uniforms, exec->uniforms_args.user_ptr, uniforms_size);
    if (ret) {
        ret = -EFAULT;
        goto err_free;
    }

    bo = vc4_bo_create(dev, binning_size + shader_records_size + uniforms_size, 0);
    if (IS_ERR(bo)) {
        ret = PTR_ERR(bo);
        goto err_free;
    }

    memcpy(bo->vaddr, binning_cmd_list, binning_size);
    memcpy((u8 *)bo->vaddr + binning_size, shader_records, shader_records_size);
    memcpy((u8 *)bo->vaddr + binning_size + shader_records_size, uniforms, uniforms_size);

    exec->bo = bo;
    exec->cmd_list_offset = 0;
    exec->shader_records_offset = binning_size;
    exec->uniforms_offset = binning_size + shader_records_size;

    ret = vc4_wait_for_rendering(dev, exec);
    if (ret)
        goto err_free;

    kfree(binning_cmd_list);
    kfree(shader_records);
    kfree(uniforms);

    return 0;

err_free:
    kfree(binning_cmd_list);
    kfree(shader_records);
    kfree(uniforms);
    return ret;
}

int vc4_prepare_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    void *bin, *shader_records, *uniforms;
    unsigned int bin_size, shader_records_size, uniforms_size;
    int ret;

    bin_size = ...; /* Compute bin size */
    shader_records_size = ...; /* Compute shader records size */
    uniforms_size = ...; /* Compute uniforms size */

    bin = kmalloc(bin_size, GFP_KERNEL);
    if (!bin)
        return -ENOMEM;

    shader_records = kmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto free_bin;
    }

    uniforms = kmalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms) {
        ret = -ENOMEM;
        goto free_shader_records;
    }

    if (copy_from_user(bin, exec->cmdlist, bin_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    if (copy_from_user(shader_records, exec->shader_records, shader_records_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    if (copy_from_user(uniforms, exec->uniforms, uniforms_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    /* Validate command list and shader records */
    if (!validate_cmdlist_and_shader_records(bin, shader_records)) {
        ret = -EINVAL;
        goto free_uniforms;
    }

    /* Create a buffer object for execution */
    exec->bo = drm_gem_cma_create(dev, bin_size + shader_records_size + uniforms_size);
    if (!exec->bo) {
        ret = -ENOMEM;
        goto free_uniforms;
    }

    /* Copy data into the BO */
    ret = drm_gem_cma_vmap(exec->bo);
    if (ret)
        goto free_bo;

    memcpy(exec->bo->vaddr, bin, bin_size);
    memcpy(exec->bo->vaddr + bin_size, shader_records, shader_records_size);
    memcpy(exec->bo->vaddr + bin_size + shader_records_size, uniforms, uniforms_size);

    drm_gem_cma_vunmap(exec->bo);

    /* Wait for any previous rendering to complete */
    ret = vc4_wait_rendering_complete(dev);
    if (ret)
        goto free_bo;

    kfree(uniforms);
    kfree(shader_records);
    kfree(bin);

    return 0;

free_uniforms:
    kfree(uniforms);
free_shader_records:
    kfree(shader_records);
free_bin:
    kfree(bin);
free_bo:
    drm_gem_object_put(exec->bo);

    return ret;
}

int vc4_prepare_binning_command(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    unsigned int binning_offset, shader_record_offset, uniform_offset;
    void *binning_cmd_list, *shader_records, *uniforms;
    struct drm_gem_cma_object *bo;

    binning_offset = 0;
    shader_record_offset = 0;
    uniform_offset = 0;

    binning_cmd_list = kmalloc(exec->bin_cmd_list_size, GFP_KERNEL);
    if (!binning_cmd_list) {
        return -ENOMEM;
    }

    shader_records = kmalloc(exec->shader_record_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto free_binning_cmd_list;
    }

    uniforms = kmalloc(exec->uniform_size, GFP_KERNEL);
    if (!uniforms) {
        ret = -ENOMEM;
        goto free_shader_records;
    }

    if (copy_from_user(binning_cmd_list, u64_to_user_ptr(exec->bin_cmd_list_ptr),
                       exec->bin_cmd_list_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->shader_record_ptr),
                       exec->shader_record_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    if (copy_from_user(uniforms, u64_to_user_ptr(exec->uniform_ptr), exec->uniform_size)) {
        ret = -EFAULT;
        goto free_uniforms;
    }

    bo = kzalloc(sizeof(*bo), GFP_KERNEL);
    if (!bo) {
        ret = -ENOMEM;
        goto free_uniforms;
    }

    ret = drm_gem_cma_create(dev, exec->bin_cmd_bo_size, &bo);
    if (ret) {
        goto free_bo;
    }

    ret = vc4_validate_cmd_list(dev, binning_cmd_list, shader_records, uniforms);
    if (ret) {
        goto free_bo;
    }

    ret = vc4_wait_for_previous_rendering(dev, exec);
    if (ret) {
        goto free_bo;
    }

    /* Additional BO setup and command list setup here */
    return 0;

free_bo:
    kfree(bo);
free_uniforms:
    kfree(uniforms);
free_shader_records:
    kfree(shader_records);
free_binning_cmd_list:
    kfree(binning_cmd_list);
    return ret;
}

int vc4_get_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    int ret;
    void *vaddr;
    size_t binning_size, shader_records_size, uniforms_size;
    unsigned int offset;

    binning_size = exec->binning_cmdlist_size;
    shader_records_size = exec->shader_records_size;
    uniforms_size = exec->uniforms_size;

    if (binning_size > 0x100000 || shader_records_size > 0x100000 || uniforms_size > 0x100000)
        return -EINVAL;

    bo = vc4_bo_create(dev, binning_size + shader_records_size + uniforms_size, 0, DRM_VMA_USEABLE);
    if (IS_ERR(bo)) {
        return PTR_ERR(bo);
    }

    vaddr = vc4_bo_map(bo);
    if (!vaddr) {
        ret = -ENOMEM;
        goto fail_map;
    }

    if (copy_from_user(vaddr, exec->user_binning_cmdlist, binning_size)) {
        ret = -EFAULT;
        goto fail_copy_binning;
    }

    offset = binning_size;
    if (copy_from_user(vaddr + offset, exec->user_shader_records, shader_records_size)) {
        ret = -EFAULT;
        goto fail_copy_shader;
    }

    offset += shader_records_size;
    if (copy_from_user(vaddr + offset, exec->user_uniforms, uniforms_size)) {
        ret = -EFAULT;
        goto fail_copy_uniforms;
    }

    exec->bin_bo = bo;
    exec->bin_cmd_list = vaddr;
    exec->bin_cmd_list_size = binning_size;
    exec->shader_records = vaddr + binning_size;
    exec->shader_records_size = shader_records_size;
    exec->uniforms = vaddr + binning_size + shader_records_size;
    exec->uniforms_size = uniforms_size;

    ret = vc4_bo_emit_reloc(exec->bin_bo, dev->pdev->dma_data, 0, 0, 0);
    if (ret) {
        goto fail_reloc;
    }

    return 0;

fail_reloc:
fail_copy_uniforms:
fail_copy_shader:
    memset(vaddr + binning_size, 0, shader_records_size + uniforms_size);
fail_copy_binning:
    memset(vaddr, 0, binning_size);
fail_map:
    vc4_bo_unref(bo);
    return ret;
}
